using EmployeeDirectory.Data;
using Microsoft.EntityFrameworkCore;

namespace EmployeeDirectory.Exercises
{
    public static class DatabaseExercises
    {
        // B.11.2 - Executes a LINQ query against the EF Core DbContext
        // and exposes the SQL generated by EF Core through ToQueryString().
        public static DatabaseQueryResult GetHighSalaryEmployeesFromDatabase(
            EmployeeDirectoryDbContext context)
        {
            var query = context.Employees
                .Where(e => e.Salary >= 12000)
                .OrderByDescending(e => e.Salary)
                .Select(e => new EmployeeDatabaseResult(
                    e.Id,
                    e.Name,
                    e.Salary));

            var sql = query.ToQueryString();

            var employees = query.ToList();

            return new DatabaseQueryResult(
                employees,
                sql);
        }

        // B.11.3 - Loads employees together with their related Department,
        // JobRole, and JobRole.Department entities using Include and ThenInclude.
        public static IReadOnlyList<EmployeeDirectory.Data.DatabaseModels.Employee> GetEmployeesWithInclude(
            EmployeeDirectoryDbContext context)
        {
            return context.Employees
                .Include(e => e.Department)
                .Include(e => e.JobRole)
                    .ThenInclude(j => j.Department)
                .AsNoTracking()
                .ToList();
        }

        // B.11.3 - Uses DTO projection to request only the columns needed
        // instead of loading complete Employee, Department, and JobRole entities.
        public static IReadOnlyList<EmployeeProjectionResult> GetEmployeesWithProjection(
            EmployeeDirectoryDbContext context)
        {
            return context.Employees
                .AsNoTracking()
                .Select(e => new EmployeeProjectionResult(
                    e.Id,
                    e.Name,
                    e.Department.Name,
                    e.JobRole.Title))
                .ToList();
        }

        public record EmployeeDatabaseResult(
            int Id,
            string Name,
            decimal Salary);

        public record DatabaseQueryResult(
            IReadOnlyList<EmployeeDatabaseResult> Employees,
            string Sql);

        public record EmployeeWithRelationsResult(
            int Id,
            string Name,
            string DepartmentName,
            string JobRoleTitle,
            string JobRoleDepartmentName);

        public record EmployeeProjectionResult(
            int Id,
            string Name,
            string DepartmentName,
            string JobRoleTitle);


        // B.11.4 - Demonstrates the N+1 problem by loading employees first
        // and then explicitly loading each employee's Department separately.
        public static int DemonstrateNPlusOne(
            EmployeeDirectoryDbContext context)
        {
            var employees = context.Employees
                .AsNoTracking()
                .ToList();

            var departmentCount = employees
                .Select(employee => context.Departments
                    .AsNoTracking()
                    .FirstOrDefault(department =>
                        department.Id == employee.DepartmentId))
                .Count(department => department != null);

            return departmentCount;
        }

        // B.11.4 - Fixes the N+1 problem by loading employees and departments
        // through a single EF Core query using Include.
        public static int DemonstrateNPlusOneFix(
            EmployeeDirectoryDbContext context)
        {
            var employees = context.Employees
                .Include(employee => employee.Department)
                .AsNoTracking()
                .ToList();

            return employees
                .Count(employee => employee.Department != null);
        }


        // B.11.5 - Demonstrates server-side evaluation where EF Core
        // translates the LINQ condition into SQL and executes it in the database.
        public static IReadOnlyList<EmployeeDatabaseResult> GetServerSideEmployees(
            EmployeeDirectoryDbContext context)
        {
            return context.Employees
                .Where(employee => employee.Salary >= 12000)
                .OrderByDescending(employee => employee.Salary)
                .Select(employee => new EmployeeDatabaseResult(
                    employee.Id,
                    employee.Name,
                    employee.Salary))
                .ToList();
        }

        // B.11.5 - Demonstrates client-side evaluation by materializing the
        // query first and then applying a C# method that runs in application memory.
        public static IReadOnlyList<EmployeeDatabaseResult> GetClientSideEmployees(
            EmployeeDirectoryDbContext context)
        {
            return context.Employees
                .AsNoTracking()
                .ToList()
                .Where(employee => IsHighSalary(employee.Salary))
                .OrderByDescending(employee => employee.Salary)
                .Select(employee => new EmployeeDatabaseResult(
                    employee.Id,
                    employee.Name,
                    employee.Salary))
                .ToList();
        }

        private static bool IsHighSalary(decimal salary)
        {
            return salary >= 12000;
        }


        // B.11.6 - Reads employees asynchronously without tracking them,
        // which reduces EF Core memory overhead for read-only queries.
        // CancellationToken allows the database operation to be cancelled safely.
        public static async Task<IReadOnlyList<EmployeeDatabaseResult>> GetEmployeesReadOnlyAsync(
            EmployeeDirectoryDbContext context,
            CancellationToken cancellationToken)
        {
            return await context.Employees
                .AsNoTracking()
                .OrderBy(employee => employee.Id)
                .Select(employee => new EmployeeDatabaseResult(
                    employee.Id,
                    employee.Name,
                    employee.Salary))
                .ToListAsync(cancellationToken);
        }
    }



}